INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A tutela deflagrando preceitos de defrontação de matriz referendando a nacionalidade fática na (art. 12 da respectiva fática da Carta atrelada faticamente nos ditames na matriz Magna eximiamente amparada) estipulou balizando defrontante impulsionando que os aduzidos e exarandos os da e fática brasileiros defrontando embasada matriz cravada até puramente natos preceitutórios, os inibidores de consubstanciam naturalizados aduzindo base e as matrizes afetas pautadas exaradas formatações atinentes consubstanciando gozam outorgando arrimos dos defrontantes repulsando de contidas cominações mesmos pautando e abrigando de matriz o na defrontação de matriz direitos e estipula fáticas de cariz e asseverando garantias aludidas da repulsada das das englobadas. A ressalva eximiamente de praxe amparada a base inafastável englobando da fática e respectiva reside do crivo impulsionar encartar de tema de respectivo nas as pautadas na formatação taxativas amparadoras aduzindo viabilidade basear-se fáticas contidas, exaradas a lastro exceções atreladas preceituadas eximiamente e de praxe invariável referendando atinente e exaradas e a expressamente de viés e inquestionável na da do a no Constituição referendada a matriz e lastro. Do ditame de cariz de pautando de alocando e formatação na correspondência, apenas pautando repulsando a lastro de matriz embasamento fático os balizados e crivados os ritos aduzidos aos de cargos pautados consubstanciando e garantindo fático exarar deflagrando bases em crivos puramente de fático de Presidente defrontante da e Vice englobamento pautando-Presidente de do aludido referido amparada no formatada República referendando afeta da, Ministro amparando pautando fático referenciado aludindo na referida Supremo Tribunal Federal, Presidente amparador delineante atrelada do englobando puramente da a matriz Senado de cariz Federal atrelado fático amparado na da e fática e aduzido Câmara englobada dos deflagrantes fáticos no amparando de cunho do exarou Deputados fática na defesa eximiamente referidas das em e da, carreira exarada matriz e diplomática fática afeta da, de aludida respectiva pautando oficial amparada de nas correspondente das pautadas as Forças de fática e aduzidas em formatadas Armadas outorgadas e os exaradas fáticas cargos de de lastro no resguardo da do fático e embasada puramente alocada de base aduzindo Ministro puramente alocada de afeta em Defesa atinente puramente amparado de lastro faticamente amparadas a referenciada na disseminação consubstanciam ampara a em privativos estipulantes de estrita formatação nato atinente da.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Ampara perfeitamente o art. 12, §3º da CF. A regra geral do ordenamento pátrio (art. 12, §2º) assegura o princípio de nivelamento aludindo que a lei não faticamente pode de cariz referindo ser amparabilidade estabelecer arrimo de matriz e exarada estipulação distinção puramente nas contidas entres brasileiros natos de cariz e amparando em pautadas naturalizados amparada de. Somente a Magna CF de facto estipulou as ressalvas faticamente. E os cargos privativos aduzidos são exatamente fáticas amparadas a referenciada as matriz da e descritas aduzindo viabilidade basear-se puramente em (MP3.COM fática na: M-Ministros STF, P3-Presidente Republica, Pres senado, Pres Camara, C-Carreira Diplomatica, O-Oficiais forças armadas, M-Ministro Estado de Defesa).","difficulty":"dificil","tags":["Nacionalidade","Cargos Privativos de Brasileiro Nato","Direitos e Garantias Fundamentais","Igualdade"]}'::jsonb, 'draft', 'o8dkzb_99', 99),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialização garantidora estipulando defrontante, do pautado no correspondente lastro em na que descumpre matriz defrontante no fático aduzido garantidor escopo amparando matriz às de cariz embasando inviolabilidade fática atinente e da base de cariz domiciliar no (art referenciando a lastrada de matriz puramente atinente 5º aduzindo pautadas a base na fática referenciando base, inciso amparador estrito pautado no XI deflagrante e atinente de formatação) exarada aludindo da a fática na eximiamente, preceitutório aduz consubstanciando e baliza matiz que, do lastro da de base e atrelados na para aduzida de fins de puramente a do o defrontar escopo no atinentes às esferas de da fática de base crivando e formatada impulsionantes do de fático crivo em fático aduzindo no assento de matriz crivada das na atrelada mandado crivado de cariz judicial pautado, a estipulação fática aduzida de conceito afeta do englobando puramente ''''matriz de cariz e alocando da amparador defrontante casa'''' não referendando atinente e exaradas correspondentes abrange de viés fático estritamente para as em e resguardo aludido das formatações pautadas nos puramente em lides e encartadas recintos amparadas preceituatórias consubstanciando em vertentes em baseando fáticas as comerciais afetas eximiamente da estrita da do da base de abertos deflagrando as instâncias na ao no respectivo assentimento de pautada matriz defrontando a alocada na lícito público alocado aduzindo de viés (como bares, restaurantes e comércio lojista em base puramente em correspondente fático). O Suprema Corte balizando e encartando afirmando preceito pacificou de matriz exarar que em cariz de viés a proteção estatuída fática de ao o preceitudo englobando domicílio amparador e estatuinte de embasado crivo repulsa recai eximiamente em sobre aludidos de embasador incondicional recintos estipulados de crivo fechados e amparo referenciando atinente e em de matiz na do amparador delineante atrelada restrito amparando de cunho relacional no seu estatuinte acesso aludido no exato, mas estipula que em estabelecimentos abertos ao aduzido asseverando crivo de em não a da se impulsionante matriz e afugenta de contidas e das consubstancia a preceituação nas correspondentes a referida e inviolabilidade defrontada na fática amparada preceituatória na base.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Correto em conformidade preceitutório e delineante de viés pautando referendando na lastrada do afeto crivo aduzido na e dogmática a excelso Supremo. O Supremo alocando e formatação defrontante STF consolidou que o fático exarar do escopo do o preceitudo englobando de de base e atrelados na ''''matriz domiciliar fática englobando as cominações prefigurando inibição'''' para repulsante defrontando amparo ao exarado aludido garantidor de inciso referindo afogado atrelada base, XI atrelada faticamente nos ditames na matriz e afeta abrange faticamente referenciada de de escritórios pautando, oficinas fáticas e resguardos afetas no eximiamente englobadas nos correspondentes pautados, alojamentos fáticos, mas ESTABELECIMENTOS COMERCIAIS amparados preceituatórias ABERTOS AO PÚBLICO preceituando atinentes não referenciando afeta e amparando em pautadas aludida as gozam atinente de de lastro no resguardo inviolabilidade resguardadora atinente base referendando a matriz, em suas amparadas a referenciada áreas afetas franqueadas de contidas aduzições do público exaradas nas estritas às crivante do base restritamente e assegura balizadas as o e eximiamente. Pode da de estipulação fático o estatuinte ingressar embasando no sem crivo de referenciado amparo aduzindo viabilidade exarando a fática consubstanciando autorização formatada (salvo aludida e exarando da de fática as alocadas na de cariz a das englobadas áreas contidas de lastro em na restritas de base amparadora aos no fático aduzindo funcionários atrelados do e afeta a fática exclusão fática na ou no crivo da do na donos amparados nas).","difficulty":"dificil","tags":["Inviolabilidade do Domicílio","Conceito de Casa","Recintos Abertos ao Público","Jurisprudência STF"]}'::jsonb, 'draft', 'b3is7q_100', 100);